/* AIPL Function: buildAgentPromptPack */
AiplVal aipl_fn_buildAgentPromptPack(void) {
  AiplVal v_lines = aipl_nil();
  v_lines = aipl_array_new(NULL, 0);
  (aipl_array_push(v_lines, aipl_str_n("# AIPL Compact Agent Prompt Pack (<4K Tokens)", 45)), aipl_nil());
  (aipl_array_push(v_lines, aipl_str_n("- Syntax: 2-space indentation blocks (`:`), `let` (immutable), `mut` (mutable), `fn name(a: int): int:`, `ret expr`.", 116)), aipl_nil());
  (aipl_array_push(v_lines, aipl_str_n("- Types: `int`, `float`, `str`, `bool`, `bytes`, `[T]`, `Map[K, V]`, `Set[T]`, `Option[T]` (`?T`), `Result[T, E]` (`T!E`).", 122)), aipl_nil());
  (aipl_array_push(v_lines, aipl_str_n("- Contracts: `requires <pred> ensures <pred>:` on functions; `invariant <pred>` and `decreases <expr>` in loops.", 112)), aipl_nil());
  (aipl_array_push(v_lines, aipl_str_n("- UFCS Collections: `arr.map(x => x * 2)`, `arr.filter(...)`, `arr.fold(0, (a, b) => a + b)`, `map.set(k, v)`, `map.get(k)`, `map.has(k)`, `map.delete(k)`.", 155)), aipl_nil());
  (aipl_array_push(v_lines, aipl_str_n("- CLI: `aipl run <file.aipl>`, `aipl test <file_or_dir>`, `aipl verify <file.aipl> [--json] [--stream-prefix]`, `aipl wire <file.aipl> <symbol> <replacement.aipl>`.", 164)), aipl_nil());
  return aipl_array_join(v_lines, aipl_str_n("\n", 1));
}

