/* AIPL Function: cmdWindow */
__attribute__((hot)) AiplVal aipl_fn_cmdWindow(AiplVal v_cliArgs) {
  AiplVal v_sub = aipl_nil();
  AiplVal v_files = aipl_nil();
  AiplVal v_found = aipl_nil();
  AiplVal v_i = aipl_nil();
  AiplVal v_f = aipl_nil();
  AiplVal v_pidStr = aipl_nil();
  AiplVal v_fpath = aipl_nil();
  AiplVal v__ = aipl_nil();
  AiplVal v_content = aipl_nil();
  AiplVal v_fi = aipl_nil();
  AiplVal v_recArgs = aipl_nil();
  AiplVal v_ai = aipl_nil();
  AiplVal v_target = aipl_nil();
  AiplVal v_script = aipl_nil();
  AiplVal v_seatId = aipl_nil();
  AiplVal v_a = aipl_nil();
  AiplVal v_pid = aipl_nil();
  AiplVal v_seatSuffix = aipl_nil();
  AiplVal v_cmdPath = aipl_nil();
  AiplVal v_ackPath = aipl_nil();
  AiplVal v_waited = aipl_nil();
  AiplVal v_statePath = aipl_nil();
  if (aipl_truthy(aipl_lt(aipl_member_get(v_cliArgs, "len"), aipl_int(2LL)))) {
    aipl_println(aipl_str_n("Usage: aipl window <list|screenshot|record|action> [args...]", 60));
    return aipl_int(1LL);
  }
  v_sub = aipl_index_get(v_cliArgs, aipl_int(1LL));
  if (aipl_truthy(aipl_eq(v_sub, aipl_str_n("list", 4)))) {
    if (aipl_truthy(aipl_not(aipl_fn_isDir(aipl_str_n("/tmp/aipl_windows", 17))))) {
      aipl_println(aipl_str_n("No active AIPL windows found.", 29));
      return aipl_int(0LL);
    }
    v_files = aipl_fn_listDir(aipl_str_n("/tmp/aipl_windows", 17));
    v_found = aipl_array_new(NULL, 0);
    v_i = aipl_int(0LL);
    while (aipl_truthy(aipl_lt(v_i, aipl_member_get(v_files, "len")))) {
      v_f = aipl_index_get(v_files, v_i);
      if (aipl_truthy((aipl_truthy(aipl_str_starts_with(v_f, aipl_str_n("win_", 4))) ? aipl_bool(aipl_truthy(aipl_str_ends_with(v_f, aipl_str_n(".info", 5)))) : aipl_bool(false)))) {
        v_pidStr = aipl_slice(v_f, aipl_int(4LL), aipl_sub(aipl_member_get(v_f, "len"), aipl_int(5LL)));
        v_fpath = aipl_fn_pathJoin(aipl_str_n("/tmp/aipl_windows", 17), v_f);
        if (aipl_truthy((aipl_truthy(aipl_fn_isDir(aipl_str_n("/proc", 5))) ? aipl_bool(aipl_truthy(aipl_not(aipl_fn_isDir(aipl_add(aipl_str_n("/proc/", 6), v_pidStr))))) : aipl_bool(false)))) {
          v__ = aipl_fn_removeFile(v_fpath);
        }
        else {
          v_content = aipl_fn_readFile(v_fpath);
          (aipl_array_push(v_found, aipl_str_trim(aipl_str_replace(v_content, aipl_str_n("\n", 1), aipl_str_n(" ", 1)))), aipl_nil());
        }
      }
      aipl_inc_int(&v_i, 1LL);
    }
    if (aipl_truthy(aipl_eq(aipl_member_get(v_found, "len"), aipl_int(0LL)))) {
      aipl_println(aipl_str_n("No active AIPL windows found.", 29));
      return aipl_int(0LL);
    }
    aipl_println(aipl_add(aipl_add(aipl_str_n("Active AIPL Windows (", 21), aipl_to_str(aipl_member_get(v_found, "len"))), aipl_str_n("):", 2)));
    v_fi = aipl_int(0LL);
    while (aipl_truthy(aipl_lt(v_fi, aipl_member_get(v_found, "len")))) {
      aipl_println(aipl_add(aipl_str_n("  ", 2), aipl_index_get(v_found, v_fi)));
      aipl_inc_int(&v_fi, 1LL);
    }
    return aipl_int(0LL);
  }
  else if (aipl_truthy(aipl_eq(v_sub, aipl_str_n("screenshot", 10)))) {
    if (aipl_truthy(aipl_lt(aipl_member_get(v_cliArgs, "len"), aipl_int(4LL)))) {
      aipl_println(aipl_str_n("Usage: aipl window screenshot <target> <out_path>", 49));
      return aipl_int(1LL);
    }
    return aipl_fn_cmdScreenshot(aipl_array_new((AiplVal[]){ aipl_str_n("screenshot", 10), aipl_index_get(v_cliArgs, aipl_int(2LL)), aipl_index_get(v_cliArgs, aipl_int(3LL)) }, 3));
  }
  else if (aipl_truthy(aipl_eq(v_sub, aipl_str_n("record", 6)))) {
    if (aipl_truthy(aipl_lt(aipl_member_get(v_cliArgs, "len"), aipl_int(4LL)))) {
      aipl_println(aipl_str_n("Usage: aipl window record <target> <out_path> [--frames <n>] [--fps <fps>]", 74));
      return aipl_int(1LL);
    }
    v_recArgs = aipl_array_new((AiplVal[]){ aipl_str_n("record", 6), aipl_index_get(v_cliArgs, aipl_int(2LL)), aipl_index_get(v_cliArgs, aipl_int(3LL)) }, 3);
    v_ai = aipl_int(4LL);
    while (aipl_truthy(aipl_lt(v_ai, aipl_member_get(v_cliArgs, "len")))) {
      (aipl_array_push(v_recArgs, aipl_index_get(v_cliArgs, v_ai)), aipl_nil());
      aipl_inc_int(&v_ai, 1LL);
    }
    return aipl_fn_cmdRecord(v_recArgs);
  }
  else if (aipl_truthy(aipl_eq(v_sub, aipl_str_n("action", 6)))) {
    if (aipl_truthy(aipl_lt(aipl_member_get(v_cliArgs, "len"), aipl_int(4LL)))) {
      aipl_println(aipl_str_n("Usage: aipl window action <target> <bot_script> [--seat <seat_id>]", 66));
      return aipl_int(1LL);
    }
    v_target = aipl_index_get(v_cliArgs, aipl_int(2LL));
    v_script = aipl_index_get(v_cliArgs, aipl_int(3LL));
    v_seatId = aipl_int(0LL);
    v_ai = aipl_int(4LL);
    while (aipl_truthy(aipl_lt(v_ai, aipl_member_get(v_cliArgs, "len")))) {
      v_a = aipl_index_get(v_cliArgs, v_ai);
      if (aipl_truthy((aipl_truthy(aipl_eq(v_a, aipl_str_n("--seat", 6))) ? aipl_bool(aipl_truthy(aipl_lt(aipl_add(v_ai, aipl_int(1LL)), aipl_member_get(v_cliArgs, "len")))) : aipl_bool(false)))) {
        v_seatId = aipl_to_int(aipl_index_get(v_cliArgs, aipl_add(v_ai, aipl_int(1LL))));
        aipl_inc_int(&v_ai, 2LL);
      }
      else if (aipl_truthy(aipl_str_starts_with(v_a, aipl_str_n("--seat=", 7)))) {
        v_seatId = aipl_to_int(aipl_slice(v_a, aipl_int(7LL), aipl_member_get(v_a, "len")));
        aipl_inc_int(&v_ai, 1LL);
      }
      else {
        aipl_inc_int(&v_ai, 1LL);
      }
    }
    v_pid = aipl_fn_resolveWindowTargetPid(v_target);
    if (aipl_truthy(aipl_le(v_pid, aipl_int(0LL)))) {
      aipl_fn_eprintln(aipl_add(aipl_str_n("[AIPL] Target window not found: ", 32), v_target));
      return aipl_int(1LL);
    }
    v_seatSuffix = (aipl_truthy((aipl_truthy(aipl_ge(v_seatId, aipl_int(1LL))) ? aipl_bool(aipl_truthy(aipl_le(v_seatId, aipl_int(8LL)))) : aipl_bool(false))) ? aipl_add(aipl_str_n(".", 1), aipl_to_str(v_seatId)) : aipl_str(""));
    v_cmdPath = aipl_add(aipl_add(aipl_add(aipl_str_n("/tmp/aipl_windows/win_", 22), aipl_to_str(v_pid)), aipl_str_n(".cmd", 4)), v_seatSuffix);
    v_ackPath = aipl_add(aipl_add(aipl_add(aipl_str_n("/tmp/aipl_windows/win_", 22), aipl_to_str(v_pid)), aipl_str_n(".ack", 4)), v_seatSuffix);
    if (aipl_truthy(aipl_fn_fileExists(v_ackPath))) {
      aipl_fn_removeFile(v_ackPath);
    }
    aipl_fn_writeFile(v_cmdPath, aipl_add(aipl_add(aipl_str_n("action:", 7), v_script), aipl_str_n("\n", 1)));
    v_waited = aipl_int(0LL);
    while (aipl_truthy(aipl_lt(v_waited, aipl_int(30LL)))) {
      if (aipl_truthy(aipl_fn_fileExists(v_ackPath))) {
        aipl_fn_removeFile(v_ackPath);
        aipl_println(aipl_add(aipl_str_n("[AIPL] Action dispatched successfully to window ", 48), v_target));
        return aipl_int(0LL);
      }
      aipl_fn_execCommand(aipl_str_n("sleep", 5), aipl_array_new((AiplVal[]){ aipl_str_n("0.05", 4) }, 1));
      aipl_inc_int(&v_waited, 1LL);
    }
    aipl_fn_eprintln(aipl_str_n("[AIPL] Timeout waiting for window action ack", 44));
    return aipl_int(1LL);
  }
  else if (aipl_truthy(aipl_eq(v_sub, aipl_str_n("state", 5)))) {
    v_target = (aipl_truthy(aipl_ge(aipl_member_get(v_cliArgs, "len"), aipl_int(3LL))) ? aipl_index_get(v_cliArgs, aipl_int(2LL)) : aipl_str_n("all", 3));
    v_pid = aipl_fn_resolveWindowTargetPid(v_target);
    if (aipl_truthy(aipl_le(v_pid, aipl_int(0LL)))) {
      aipl_fn_eprintln(aipl_add(aipl_str_n("[AIPL] Target window not found: ", 32), v_target));
      return aipl_int(1LL);
    }
    v_statePath = aipl_add(aipl_add(aipl_str_n("/tmp/aipl_windows/win_", 22), aipl_to_str(v_pid)), aipl_str_n(".state.json", 11));
    if (aipl_truthy(aipl_not(aipl_fn_fileExists(v_statePath)))) {
      aipl_fn_eprintln(aipl_add(aipl_str_n("[AIPL] Window state telemetry not found: ", 41), v_statePath));
      return aipl_int(1LL);
    }
    aipl_println(aipl_fn_readFile(v_statePath));
    return aipl_int(0LL);
  }
  else {
    aipl_fn_eprintln(aipl_add(aipl_str_n("Unknown window command: ", 24), v_sub));
    return aipl_int(1LL);
  }
}

